import random

K=[1,2,3,2,1]
def med(a):
    s=sorted(a); m=len(s); h=m//2
    return s[h] if m%2 else (s[h-1]+s[h])/2
def despike(src, half=2, sigmas=3.0):
    n=len(src)
    if n<=2: return list(src)
    out=list(src)
    for i in range(n):
        lo=max(0,i-half); hi=min(n-1,i+half)
        w=src[lo:hi+1]; m=med(w)
        mad=med([abs(v-m) for v in w])
        if abs(src[i]-m) > sigmas*1.4826*mad: out[i]=m
    return out
def smooth_once(src):
    n=len(src); out=[0.0]*n
