        s=0.0; ws=0.0
        for k,wk in enumerate(K):
            j=i+k-2
            if 0<=j<n: s+=src[j]*wk; ws+=wk
        out[i]=s/ws
    return out
def smooth(src, passes=2):
    if len(src)<=2: return list(src)
    cur=list(src)
