      final out = RideSeriesSmooth.prepare(ramp);
      for (var i = 1; i < out.length; i++) {
        expect(out[i], greaterThanOrEqualTo(out[i - 1]));
      }
    });

    test('不越界外插：min/max 不超出原始范围', () {
