  check('ds len', dso.length == 100);
  check('ds first', dso.first == -5, dso.first);
  check('ds last', dso.last == 500, dso.last);
  final mid = RideSeriesSmooth.downsample(<double>[0, 10, 20, 30, 40, 50], 4);
  check('ds mid', mid.join(',') == '0.0,15.0,35.0,50.0', mid);
  check('ds maxN2', RideSeriesSmooth.downsample([for (var i = 0; i < 10; i++) i.toDouble()], 2).join(',') == '0.0,9.0');
  check('ds short', RideSeriesSmooth.downsample(<double>[1, 2, 3], 160).join(',') == '1.0,2.0,3.0');

  // prepare 长度/边界
  final big = [for (var i = 0; i < 1000; i++) i.toDouble()];
  final bp = RideSeriesSmooth.prepare(big);
  check('prepare 160', bp.length == 160, bp.length);
  check('prepare short', RideSeriesSmooth.prepare([for (var i = 0; i < 20; i++) i * 1.5]).length == 20);
  final wave = [for (var i = 0; i < 500; i++) 30 + 12 * math.sin(i / 9)];
  final wo = RideSeriesSmooth.prepare(wave);
  final lo = wave.reduce(math.min), hi = wave.reduce(math.max);
  check('prepare min', wo.reduce(math.min) >= lo - 1e-9, [wo.reduce(math.min), lo]);
  check('prepare max', wo.reduce(math.max) <= hi + 1e-9, [wo.reduce(math.max), hi]);
